const subscriptions = new Set();

export async function listTools() {
  return [
    {
      name: 'subscribeResource',
      description: 'Subscribe to a resource by URI. Rejects empty URIs and duplicate subscriptions.',
      inputSchema: {
        type: 'object',
        properties: {
          uri: { type: 'string', description: 'Non-empty resource URI to subscribe to.' }
        },
        required: ['uri']
      }
    },
    {
      name: 'unsubscribeResource',
      description: 'Unsubscribe from a resource by URI. Rejects missing subscriptions.',
      inputSchema: {
        type: 'object',
        properties: {
          uri: { type: 'string', description: 'Resource URI to unsubscribe from.' }
        },
        required: ['uri']
      }
    }
  ];
}

export async function subscribeResource(uri) {
  if (typeof uri !== 'string' || uri.trim() === '') {
    throw new Error('uri must be a non-empty string');
  }
  if (subscriptions.has(uri)) {
    throw new Error('already subscribed to ' + uri);
  }
  subscriptions.add(uri);
  return { uri, subscribed: true };
}

export async function unsubscribeResource(uri) {
  if (typeof uri !== 'string' || uri.trim() === '') {
    throw new Error('uri must be a non-empty string');
  }
  if (!subscriptions.has(uri)) {
    throw new Error('not subscribed to ' + uri);
  }
  subscriptions.delete(uri);
  return { uri, unsubscribed: true };
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'subscribeResource':
      return await subscribeResource(args.uri);
    case 'unsubscribeResource':
      return await unsubscribeResource(args.uri);
    default:
      throw new Error('unknown tool: ' + name);
  }
}

